/* What buyers paid for and what Storelib AI was used for are not deleted with the public key (round AW, database security). Every page holds the public key and every signed in person their own token, so anybody can call the database's REST API directly, past the app's routes. Old policies let that delete what the app itself never deletes from the browser: "Creators can delete their own products", "Users can delete their own creator profile" and sites_own (FOR ALL). A product deleted that way takes every buyer's library row for it (entitlements), its refunds, reviews, course enrollments and file records with it, by ON DELETE CASCADE; a store (creators) takes its orders, library rows, refunds, payouts, seller ledger, invoices, subscriptions, payment balances and about a hundred more tables; an AI site takes its site_agent_runs, which the month's Storelib AI allowance and its hourly limit are counted from (lib/sites/agent/run.ts, lib/sites/rate-limit.ts), so deleting a used site and making a new one handed back the month's paid AI edits. The app deletes products and stores on the server with the service role, after its own checks: /api/products/delete archives a product anybody bought (lib/products/delete-product.ts) and account deletion retires a store that has money records (lib/account/delete-account.ts); no page deletes either with the browser key (the old product edit form that did is used by no page). No screen deletes an AI site; the one delete of a site, the clean up when a new site's first files did not save (lib/sites/projects.ts), runs with the creator's own key on a site that has no AI run yet. So: DELETE and TRUNCATE on public.products and public.creators are taken from anon and authenticated, and a trigger, sites_keep_ai_runs, refuses a delete of a site that has Storelib AI runs when it comes with the browser key (anon or authenticated), with SQLSTATE 42501. The helper it asks, public.storelib_site_has_ai_runs(uuid), runs with its owner's rights so the answer does not depend on what the caller may read, and says only yes or no. It does NOT change any row or policy, nor reading, adding or editing these tables, nor the clean up of a site with no run, and the service role (the server, account deletion, the admin) deletes as before. A table that is not here is skipped with a notice. LOCKS: REVOKE and CREATE TRIGGER take a short lock on products, creators and sites, held until the paste ends; well under a second. Safe to run again. */
DO $do$ DECLARE t text; BEGIN FOREACH t IN ARRAY ARRAY['products', 'creators'] LOOP IF to_regclass('public.' || t) IS NULL THEN RAISE NOTICE 'part 452: public.% does not exist here, skipped', t; CONTINUE; END IF; EXECUTE format('REVOKE DELETE, TRUNCATE ON public.%I FROM PUBLIC, anon, authenticated', t); END LOOP; END $do$;
CREATE OR REPLACE FUNCTION public.storelib_site_has_ai_runs(p_site uuid) RETURNS boolean LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = public AS $f$ BEGIN IF p_site IS NULL OR to_regclass('public.site_agent_runs') IS NULL THEN RETURN false; END IF; RETURN EXISTS (SELECT 1 FROM public.site_agent_runs r WHERE r.site_id = p_site); END $f$;
REVOKE ALL ON FUNCTION public.storelib_site_has_ai_runs(uuid) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.storelib_site_has_ai_runs(uuid) TO authenticated, service_role;
CREATE OR REPLACE FUNCTION public.sites_keep_ai_runs() RETURNS trigger LANGUAGE plpgsql SET search_path = public AS $f$ BEGIN IF current_user IN ('authenticated', 'anon') AND public.storelib_site_has_ai_runs(OLD.id) THEN RAISE EXCEPTION 'This site has used Storelib AI, so it is not deleted from here.' USING ERRCODE = '42501'; END IF; RETURN OLD; END $f$;
REVOKE ALL ON FUNCTION public.sites_keep_ai_runs() FROM PUBLIC, anon, authenticated;
DO $do$ BEGIN IF to_regclass('public.sites') IS NULL THEN RAISE NOTICE 'part 452: public.sites does not exist here, sites_keep_ai_runs skipped'; RETURN; END IF; DROP TRIGGER IF EXISTS sites_keep_ai_runs ON public.sites; CREATE TRIGGER sites_keep_ai_runs BEFORE DELETE ON public.sites FOR EACH ROW EXECUTE FUNCTION public.sites_keep_ai_runs(); END $do$;
notify pgrst, 'reload schema';
